// ========================================================
// 📏 연산 멀티 스튜디오 - 수직선 (모델 + 화면)
// 모델은 DOM을 쓰지 않는 순수 계산이고, 화면은 모델만 그린다.
// ========================================================
(() => {
  'use strict';

  // ========================================================
  // 📏 수직선 모델: 점프 목록과 눈금 위치(%)
  // ========================================================
  const MAX_DRAWN_JUMPS = 12;

  // 점프가 많으면 앞뒤만 그리고 줄인 구간에 칸을 하나 비운다. 축은 비례가 아니라 고른 칸이 된다.
  function compressedPosition(sorted, gapStart) {
    const gapIndex = sorted.indexOf(gapStart);
    const slotCount = sorted.length;
    return {
      gapPos: ((gapIndex + 1) / slotCount) * 100,
      position: value => {
        const index = sorted.indexOf(value);
        return ((index > gapIndex ? index + 1 : index) / slotCount) * 100;
      }
    };
  }

  function repeatedJumpIndexes(total, maxJumps) {
    const compressed = total > maxJumps;
    const edgeJumps = Math.floor((maxJumps - 2) / 2);
    const indexes = [];
    for (let i = 1; i <= total; i++) {
      if (!compressed || i <= edgeJumps || i > total - edgeJumps) indexes.push(i);
    }
    return { compressed, edgeJumps, indexes };
  }

  function finishLineModel(model, jumps, sorted, position) {
    return {
      ...model,
      jumps: jumps.map(jump => ({ ...jump, fromPos: position(jump.from), toPos: position(jump.to) })),
      ticks: sorted.map((value, i) => ({ value, pos: position(value), low: i % 2 === 0 }))
    };
  }

  // ➗ 나누어지는 수에서 나누는 수씩 뒤로 뛴다
  function buildNumberLineModel(dividend, divisor, maxJumps = MAX_DRAWN_JUMPS) {
    const quotient = Math.floor(dividend / divisor);
    const remainder = dividend % divisor;
    const { compressed, edgeJumps, indexes } = repeatedJumpIndexes(quotient, maxJumps);
    const jumps = indexes.map(index => ({
      index,
      from: dividend - (index - 1) * divisor,
      to: dividend - index * divisor
    }));

    const values = new Set([0, remainder, dividend]);
    jumps.forEach(jump => { values.add(jump.from); values.add(jump.to); });
    const sorted = [...values].sort((a, b) => a - b);

    let gap = null;
    let position = value => (value / dividend) * 100;
    if (compressed) {
      const layout = compressedPosition(sorted, dividend - (quotient - edgeJumps) * divisor);
      position = layout.position;
      gap = { skipped: quotient - edgeJumps * 2, pos: layout.gapPos };
    }

    return finishLineModel(
      { op: 'div', dividend, divisor, quotient, remainder, compressed, gap, startVal: dividend, endVal: remainder, totalJumps: quotient },
      jumps,
      sorted,
      position
    );
  }

  // ✖️ 0에서 곱해지는 수씩 앞으로 뛴다
  function buildMultiplicationLineModel(numA, numB, maxJumps = MAX_DRAWN_JUMPS) {
    const product = numA * numB;
    const { compressed, edgeJumps, indexes } = repeatedJumpIndexes(numB, maxJumps);
    const jumps = indexes.map(index => ({ index, from: (index - 1) * numA, to: index * numA }));

    const values = new Set([0, product]);
    jumps.forEach(jump => { values.add(jump.from); values.add(jump.to); });
    const sorted = [...values].sort((a, b) => a - b);

    let gap = null;
    let position = value => (value / product) * 100;
    if (compressed) {
      const layout = compressedPosition(sorted, edgeJumps * numA);
      position = layout.position;
      gap = { skipped: numB - edgeJumps * 2, pos: layout.gapPos };
    }

    return finishLineModel(
      { op: 'mul', numA, numB, compressed, gap, startVal: 0, endVal: product, totalJumps: numB },
      jumps,
      sorted,
      position
    );
  }

  // ➕➖ 자리별로 나누어 뛴다 (+400, +20, +5). 작은 점프도 보이도록 칸 너비에 하한을 둔다.
  function buildPlaceJumpLineModel(op, numA, numB) {
    if (op === 'sub' && numA < numB) return { op, blocked: true };

    const sign = op === 'add' ? 1 : -1;
    const symbol = op === 'add' ? '+' : '−';
    const parts = [100, 10, 1]
      .map(unit => Math.floor(numB / unit) % 10 * unit)
      .filter(part => part > 0);

    let current = numA;
    const jumps = parts.map((part, i) => {
      const from = current;
      current += sign * part;
      return { index: i + 1, from, to: current, label: `${symbol}${part}` };
    });

    const sorted = [...new Set([numA, current])].concat(jumps.map(jump => jump.to))
      .filter((value, i, list) => list.indexOf(value) === i)
      .sort((a, b) => a - b);
    const widths = sorted.slice(1).map((value, i) => Math.max(value - sorted[i], numB * 0.2));
    const widthTotal = widths.reduce((sum, width) => sum + width, 0);
    const positions = new Map([[sorted[0], 0]]);
    let walked = 0;
    widths.forEach((width, i) => {
      walked += width;
      positions.set(sorted[i + 1], (walked / widthTotal) * 100);
    });

    return finishLineModel(
      { op, numA, numB, compressed: false, gap: null, startVal: numA, endVal: current, totalJumps: jumps.length },
      jumps,
      sorted,
      value => positions.get(value)
    );
  }

  function buildOpNumberLineModel(op, numA, numB) {
    if (op === 'div') return buildNumberLineModel(numA, numB);
    if (op === 'mul') return buildMultiplicationLineModel(numA, numB);
    return buildPlaceJumpLineModel(op, numA, numB);
  }

  window.OperatorStudioLines = { buildNumberLineModel, buildOpNumberLineModel };
})();

// ========================================================
// 📏 [탭 3] 수직선 렌더링 (4대 연산 공통)
// 실제 수직선 위에서 "다음 점프"를 누를 때마다 한 번씩 뛴다.
// ========================================================
function numberLineSpeech(model, step) {
  const { op, jumps, startVal, endVal } = model;
  const eul = n => `${n}${numberJosa(n, '을', '를')}`;
  const eun = n => `${n}${numberJosa(n, '은', '는')}`;
  const ieyo = n => `${n}${numberJosa(n, '이에요', '예요')}`;

  if (op === 'div') {
    const resultText = divisionResultText(model.quotient, model.remainder);
    if (jumps.length === 0) return `${startVal}에서는 ${eul(model.divisor)} 한 번도 뺄 수 없어요. ${resultText}`;
    if (step === 0) return `수직선에서 ${startVal}부터 ${model.divisor}씩 뒤로 뛰어 볼까요? 다음 점프 버튼을 눌러 보세요!`;
    const jump = jumps[step - 1];
    const previous = jumps[step - 2];
    const skipped = previous && jump.index > previous.index + 1 ? `중간의 ${jump.index - previous.index - 1}번은 건너뛰고, ` : '';
    const text = `${skipped}${jump.from}에서 ${eul(model.divisor)} 빼면 ${jump.to}! ${jump.index}번 뛰었어요.`;
    return step === jumps.length ? `${text} 더는 뛸 수 없어요. ${resultText}` : text;
  }

  if (op === 'mul') {
    if (step === 0) return `수직선에서 0부터 ${model.numA}씩 ${model.numB}번 앞으로 뛰어 볼까요? 다음 점프 버튼을 눌러 보세요!`;
    const jump = jumps[step - 1];
    const previous = jumps[step - 2];
    const skipped = previous && jump.index > previous.index + 1 ? `중간의 ${jump.index - previous.index - 1}번은 건너뛰고, ` : '';
    const text = `${skipped}${jump.from}에서 ${model.numA}만큼 뛰면 ${jump.to}! ${jump.index}번 뛰었어요.`;
    return step === jumps.length ? `${text} ${model.numA} 곱하기 ${eun(model.numB)} ${ieyo(endVal)}.` : text;
  }

  const direction = op === 'add' ? '앞으로' : '뒤로';
  if (step === 0) return `수직선에서 ${startVal}부터 ${model.numB}만큼 ${direction} 뛰어 볼까요? 자리별로 나누어 뛰어요!`;
  const jump = jumps[step - 1];
  const text = `${jump.from}에서 ${Math.abs(jump.to - jump.from)}만큼 ${direction} 뛰면 ${jump.to}!`;
  const wordOp = op === 'add' ? '더하기' : '빼기';
  return step === jumps.length ? `${text} ${startVal} ${wordOp} ${eun(model.numB)} ${ieyo(endVal)}.` : text;
}

// 연산별 안내 글자와 결과 칸
function numberLineSummary(model, currentValue, jumpCount, isDone) {
  const { op, startVal, endVal } = model;
  if (op === 'div') {
    return {
      pill: `${model.divisor}씩 뒤로 뛰기 (${jumpCount} / ${model.quotient}번)`,
      equation: isDone
        ? `${startVal} - (${model.divisor} × ${model.quotient}) = <span style="color:#ef4444;">${model.remainder}</span>`
        : `${startVal} - (${model.divisor} × ${jumpCount}) = ${currentValue}`,
      leftLabel: '뛰어 덜어낸 횟수 (몫)',
      leftValue: `${jumpCount}번`,
      rightLabel: '0에 못 닿고 남은 수 (나머지)',
      rightValue: isDone ? model.remainder : '?'
    };
  }
  if (op === 'mul') {
    return {
      pill: `${model.numA}씩 앞으로 뛰기 (${jumpCount} / ${model.numB}번)`,
      equation: `${model.numA} × ${jumpCount} = ${currentValue}`,
      leftLabel: '앞으로 뛴 횟수',
      leftValue: `${jumpCount}번`,
      rightLabel: '도착한 수 (곱)',
      rightValue: isDone ? endVal : '?'
    };
  }
  const moved = Math.abs(currentValue - startVal);
  const symbol = op === 'add' ? '+' : '−';
  return {
    pill: `자리별로 ${op === 'add' ? '앞으로' : '뒤로'} 뛰기 (${jumpCount} / ${model.totalJumps}번)`,
    equation: `${startVal} ${symbol} ${moved} = ${currentValue}`,
    leftLabel: '지금까지 뛴 만큼',
    leftValue: `${symbol}${moved}`,
    rightLabel: op === 'add' ? '도착한 수 (합)' : '도착한 수 (차)',
    rightValue: isDone ? endVal : '?'
  };
}

function renderNumberLineView(container) {
  const model = window.OperatorStudioLines.buildOpNumberLineModel(currentOp, curNumA, curNumB);
  if (model.blocked) {
    renderSubtractionGuide(container);
    return;
  }

  const { jumps } = model;
  numberLineStep = Math.max(0, Math.min(jumps.length, numberLineStep));

  const isDone = numberLineStep === jumps.length;
  const currentJump = jumps[numberLineStep - 1];
  const currentValue = currentJump ? currentJump.to : model.startVal;
  const jumpCount = currentJump ? currentJump.index : 0;
  const summary = numberLineSummary(model, currentValue, jumpCount, isDone);
  const directionClass = model.op === 'add' || model.op === 'mul' ? 'nl-jump-arc--forward' : 'nl-jump-arc--back';

  // 줄인 수직선은 칸이 좁아 번호가 겹치므로 방금 뛴 점프의 번호만 적는다
  const arcsHtml = jumps.slice(0, numberLineStep).map((jump, i) => {
    const showCount = !model.compressed || i === numberLineStep - 1;
    const left = Math.min(jump.fromPos, jump.toPos);
    const width = Math.abs(jump.fromPos - jump.toPos);
    return `
      <div class="nl-jump-arc ${directionClass}" style="left:${left}%; width:${width}%;">
        ${showCount ? `<span class="nl-jump-count">${jump.label || jump.index}</span>` : ''}
      </div>
    `;
  }).join('');

  const hasLongLabels = String(Math.max(model.startVal, model.endVal)).length >= 4;
  const ticksHtml = model.ticks.map(tick => `
    <div class="nl-tick ${tick.value === currentValue ? 'nl-tick--current' : ''}" style="left:${tick.pos}%;"></div>
    <div class="nl-label ${tick.low ? 'nl-label--low' : ''} ${tick.value === currentValue ? 'nl-label--current' : ''} ${hasLongLabels ? 'nl-label--tiny' : ''}" style="left:${tick.pos}%;">${tick.value}</div>
  `).join('');

  const gapHtml = model.gap
    ? `<div class="nl-gap" style="left:${model.gap.pos}%;">⋯ ${model.gap.skipped}번 더</div>`
    : '';

  container.innerHTML = `
    <div class="numberline-wrap">
      <div class="block-step-nav">
        <span class="step-pill">📏 ${summary.pill}</span>
        <div class="nav-btn-group">
          <button class="step-control-btn" onclick="changeNumberLineStep(-1)" ${numberLineStep === 0 ? 'disabled' : ''}>◀ 이전</button>
          <button class="step-control-btn" onclick="changeNumberLineStep(1)" ${isDone ? 'disabled' : ''} style="background:#0284c7; color:#fff; border-color:#38bdf8;">다음 점프 ▶</button>
        </div>
      </div>

      <div class="nl-axis-container" role="img" aria-label="${model.startVal}에서 ${model.endVal}까지 뛰는 수직선">
        <div class="nl-track">
          <div class="nl-axis-line"></div>
          ${arcsHtml}
          ${ticksHtml}
          ${gapHtml}
        </div>
      </div>

      <div class="nl-result-card">
        <div style="font-family:'Jua'; font-size:1.5rem; color:#f59e0b; margin-bottom:16px;">${summary.equation}</div>
        <div style="display:flex; justify-content:space-around; align-items:center; flex-wrap:wrap; gap:12px;">
          <div style="background:rgba(2,132,199,0.15); border:1.5px solid #0284c7; border-radius:12px; padding:14px 20px;">
            <div style="font-size:0.9rem; color:#94a3b8;">${summary.leftLabel}</div>
            <div style="font-family:'Jua'; font-size:2rem; color:#38bdf8;">${summary.leftValue}</div>
          </div>
          <div style="background:rgba(239,68,68,0.15); border:1.5px solid #ef4444; border-radius:12px; padding:14px 20px;">
            <div style="font-size:0.9rem; color:#94a3b8;">${summary.rightLabel}</div>
            <div style="font-family:'Jua'; font-size:2rem; color:#ef4444;">${summary.rightValue}</div>
          </div>
        </div>
      </div>
    </div>
  `;

  studioSpeak(numberLineSpeech(model, numberLineStep));
}

function changeNumberLineStep(delta) {
  hasUserStarted = true;
  numberLineStep += delta;
  renderNumberLineView(document.getElementById('studioViewport'));
}
// ========================================================
// 📝 [탭 2] 단계별 격자 세로셈 튜터 렌더링 (4대 연산 지원)
// 화면은 curPlan.board만 그리므로 풀이와 화면이 일치한다.
// ========================================================

const DIVISION_ROW_COLORS = { product: '#ec4899', remainder: 'inherit' };

function renderDivisionRowCells(row, columnCount, isActive, isFinal) {
  const startCol = row.endCol - row.value.length + 1;
  let html = '';
  for (let col = 0; col < columnCount; col++) {
    const hasDigit = col >= startCol && col <= row.endCol;
    const digit = hasDigit ? row.value[col - startCol] : '';
    const classes = [];
    if (row.kind === 'product' && col >= row.lineFromCol && col <= row.endCol) classes.push('calc-step-line');
    if (isActive && hasDigit) classes.push('cell-active');

    let color = DIVISION_ROW_COLORS[row.kind];
    if (col === row.broughtCol) color = '#10b981';
    if (isFinal && row.kind === 'remainder') color = '#ef4444';

    html += `<td class="${classes.join(' ')}" style="color:${color};">${digit}</td>`;
  }
  return html;
}

function renderDivisionBoard(step, dividend, divisor) {
  const { board } = step;
  const digits = String(dividend).split('');
  const isFinalStep = step.step === currentPlan.length;

  const quotientCells = board.quotient.map((digit, col) => {
    const active = col === board.activeQuotientCol ? 'cell-active' : '';
    return `<td class="td-quotient-line ${active}">${digit}</td>`;
  }).join('');

  const dividendCells = digits.map((digit, col) => {
    const active = board.activeDividendCols.includes(col) ? 'cell-active' : '';
    return `<td class="${active}" style="color:#38bdf8;">${digit}</td>`;
  }).join('');

  const workRows = board.rows.map((row, index) => {
    const isActive = index === board.activeRow;
    const isFinalRow = isFinalStep && index === board.rows.length - 1;
    return `
      <tr>
        <td></td>
        <td>${row.kind === 'product' ? '-' : ''}</td>
        ${renderDivisionRowCells(row, digits.length, isActive, isFinalRow)}
      </tr>
    `;
  }).join('');

  return `
    <table class="division-table">
      <tr>
        <td></td>
        <td class="td-divisor-arc"></td>
        ${quotientCells}
      </tr>
      <tr>
        <td style="color:#f59e0b;">${divisor}</td>
        <td class="td-divisor-arc">)</td>
        ${dividendCells}
      </tr>
      ${workRows}
    </table>
  `;
}

// 세로 덧셈·뺄셈·곱셈 공통 줄: 가로줄은 계산 결과 바로 위(아래 수의 밑)에 긋는다
function renderOperandRows(board, sign, markBottomActive = true) {
  const activeClass = col => (col === board.activeCol ? 'cell-active' : '');
  const rowA = board.digitsA.map((digit, col) => {
    const crossed = board.borrows?.[col]?.crossed ? 'text-decoration:line-through; opacity:0.6;' : '';
    return `<td class="${activeClass(col)}" style="color:#38bdf8; ${crossed}">${digit}</td>`;
  }).join('');
  const rowB = board.digitsB.map((digit, col) => {
    const active = markBottomActive ? activeClass(col) : '';
    return `<td class="calc-step-line ${active}" style="color:#d97706;">${digit}</td>`;
  }).join('');
  return `
    <tr><td></td>${rowA}</tr>
    <tr><td class="calc-step-line" style="color:#f59e0b; font-weight:800;">${sign}</td>${rowB}</tr>
  `;
}

function renderResultRow(board) {
  const cells = board.result.map((digit, col) => {
    const active = col === board.activeCol ? 'cell-active' : '';
    return `<td class="${active}" style="color:#10b981; font-weight:800;">${digit}</td>`;
  }).join('');
  return `<tr class="result-row"><td></td>${cells}</tr>`;
}

function renderAdditionBoard(step) {
  const { board } = step;
  const carriesRow = board.carries.map((carry, col) => {
    const active = col === board.activeCarryCol ? 'cell-active' : '';
    return `<td class="${active}" style="color:#ec4899; font-weight:800;">${carry}</td>`;
  }).join('');

  return `
    <table class="division-table standard-vertical-table">
      <tr class="carry-row"><td></td>${carriesRow}</tr>
      ${renderOperandRows(board, '+')}
      ${renderResultRow(board)}
    </table>
  `;
}

// 윗줄에는 실제로 빼는 값을 적는다. 142 − 68의 십의 자리는 받아내린 뒤 13이다.
function renderSubtractionBoard(step) {
  const { board } = step;
  const borrowsRow = board.borrows.map((mark, col) => {
    if (!mark) return '<td></td>';
    const active = col === board.activeBorrowCol ? 'cell-active' : '';
    return `<td class="${active}" style="color:#ec4899; font-weight:800;">${mark.val}</td>`;
  }).join('');

  return `
    <table class="division-table standard-vertical-table">
      <tr class="carry-row"><td></td>${borrowsRow}</tr>
      ${renderOperandRows(board, '−')}
      ${renderResultRow(board)}
    </table>
  `;
}

function renderMultiplicationBoard(step) {
  const { board } = step;
  const carriesRow = board.carries.map((carry, col) => {
    const active = carry && col === board.activeCol ? 'cell-active' : '';
    return `<td class="${active}" style="color:#ec4899; font-weight:800;">${carry}</td>`;
  }).join('');

  const rowsHtml = board.rows.map((row, index) => {
    const isActive = index === board.activeRow;
    const isPart2 = row.kind === 'part2';
    const isAnswer = row.kind === 'sum' || row.kind === 'result';
    const cells = row.cells.map((digit, col) => {
      const classes = [];
      if (isPart2) classes.push('calc-step-line');
      if (isActive && (row.kind !== 'result' || col === board.activeCol)) classes.push('cell-active');
      return `<td class="${classes.join(' ')}" style="color:${isAnswer ? '#10b981' : 'inherit'}; font-weight:${isAnswer ? '800' : '700'};">${digit}</td>`;
    }).join('');
    return `
      <tr>
        <td class="${isPart2 ? 'calc-step-line' : ''}" style="color:#f59e0b; font-weight:800;">${isPart2 ? '+' : ''}</td>
        ${cells}
      </tr>
    `;
  }).join('');

  return `
    <table class="division-table standard-vertical-table">
      <tr class="carry-row"><td></td>${carriesRow}</tr>
      ${renderOperandRows(board, '×', false)}
      ${rowsHtml}
    </table>
  `;
}

function renderVerticalTutorView(container) {
  if (!currentPlan || currentPlan.length === 0) {
    startStudioCalculation(false);
  }

  const curPlan = currentPlan[tutorCurrentStep - 1] || currentPlan[0];
  if (curPlan.isNegative) {
    renderSubtractionGuide(container);
    return;
  }

  let boardMarkup = '';
  if (currentOp === 'div') {
    boardMarkup = renderDivisionBoard(curPlan, curNumA, curNumB);
  } else if (currentOp === 'add') {
    boardMarkup = renderAdditionBoard(curPlan);
  } else if (currentOp === 'sub') {
    boardMarkup = renderSubtractionBoard(curPlan);
  } else if (currentOp === 'mul') {
    boardMarkup = renderMultiplicationBoard(curPlan);
  }

  container.innerHTML = `
    <div class="vertical-tutor-container">
      <div class="division-board-card">
        ${boardMarkup}
      </div>

      <div class="tutor-guide-panel">
        <div class="tutor-step-card">
          <div class="tutor-step-title">${curPlan.title}</div>
          <div class="tutor-step-desc">${curPlan.desc}</div>
        </div>

        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
          <span style="font-family:'Jua'; color:#94a3b8;">진행: ${tutorCurrentStep} / ${currentPlan.length}단계</span>
          <div class="nav-btn-group">
            <button class="step-control-btn" onclick="changeTutorStep(-1)" ${tutorCurrentStep === 1 ? 'disabled' : ''}>◀ 이전</button>
            <button class="step-control-btn" onclick="changeTutorStep(1)" ${tutorCurrentStep === currentPlan.length ? 'disabled' : ''} style="background:#0284c7; color:#fff; border-color:#38bdf8;">다음 단계 ▶</button>
          </div>
        </div>
      </div>
    </div>
  `;

  studioSpeak(curPlan.speech);
}

function changeTutorStep(delta) {
  hasUserStarted = true;
  tutorCurrentStep = Math.max(1, Math.min(currentPlan.length, tutorCurrentStep + delta));
  renderVerticalTutorView(document.getElementById('studioViewport'));
}

// ========================================================
// 🍫 [탭 4] 면적(넓이) 모델 렌더링 (모바일 375px 무넘침 설계)
// ========================================================
function renderAreaModelView(container) {
  if (currentOp === 'mul') {
    renderMultiplicationAreaView(container);
  } else {
    renderDivisionAreaView(container);
  }
}

const AREA_BOX_COLORS = [
  { background: 'rgba(2,132,199,0.35)', text: '#38bdf8' },
  { background: 'rgba(16,185,129,0.35)', text: '#10b981' },
  { background: 'rgba(245,158,11,0.3)', text: '#d97706' },
  { background: 'rgba(168,85,247,0.3)', text: '#a855f7' }
];

function renderAreaBox(index, topText, value, bottomText = '') {
  const color = AREA_BOX_COLORS[index % AREA_BOX_COLORS.length];
  return `
    <div class="area-box" style="background:${color.background};">
      <div style="color:var(--text-muted); font-size:0.85rem;">${topText}</div>
      <div style="color:${color.text}; font-size:1.3rem;">${value}</div>
      ${bottomText ? `<div style="color:var(--text-muted); font-size:0.8rem;">${bottomText}</div>` : ''}
    </div>
  `;
}

// 더할 값이 하나뿐이면 "= 7 = 7"처럼 같은 수를 두 번 쓰지 않는다
function areaSumText(values, total, colorText) {
  const result = `<span style="color:${colorText};">${total}</span>`;
  return values.length > 1 ? `${values.join(' + ')} = ${result}` : result;
}

function renderDivisionAreaView(container) {
  const model = StudioPlans.buildAreaModel('div', curNumA, curNumB);
  const { divisor, quotient, remainder, parts } = model;

  const remainderText = remainder > 0
    ? `남는 넓이는 ${remainder}${numberJosa(remainder, '이에요', '예요')}!`
    : '남는 넓이 없이 딱 맞아요!';
  const speech = `면적 모델이에요! 가로가 ${divisor}인 직사각형의 전체 넓이가 ${curNumA}일 때, 세로 길이는 몫인 ${quotient}${numberJosa(quotient, '이', '가')} 돼요. ${remainderText}`;

  const boxesHtml = parts
    .map((part, i) => renderAreaBox(i, `세로 ${part.height}`, `넓이 ${part.area}`, `(${divisor} × ${part.height})`))
    .join('');

  container.innerHTML = `
    <div class="area-model-wrap">
      <div style="text-align:center; max-width:600px;">
        <h3 style="font-family:'Jua'; color:#38bdf8; margin:0 0 6px;">🍫 면적 분할 모델 (나눗셈)</h3>
        <p style="color:var(--text-muted); font-size:0.95rem; margin:0;">
          가로 길이가 <strong>${divisor}</strong>일 때, 넓이 <strong>${curNumA}</strong>${numberJosa(curNumA, '을', '를')} 채우는 세로 길이를 찾아요!
        </p>
      </div>

      <div class="area-rect-container">
        ${boxesHtml}
        ${remainder > 0 ? `
        <div class="area-box" style="background:rgba(239,68,68,0.2);">
          <div style="color:var(--text-muted); font-size:0.85rem;">남은 넓이</div>
          <div style="color:#ef4444; font-size:1.3rem;">${remainder}</div>
          <div style="color:var(--text-muted); font-size:0.8rem;">(나머지)</div>
        </div>
        ` : ''}
      </div>

      <div class="area-total">
        전체 세로 길이(몫) = ${areaSumText(parts.map(part => part.height), quotient, '#38bdf8')}
        ${remainder > 0 ? ` (나머지: <span style="color:#ef4444;">${remainder}</span>)` : ''}
      </div>
    </div>
  `;
  studioSpeak(speech);
}

function renderMultiplicationAreaView(container) {
  const model = StudioPlans.buildAreaModel('mul', curNumA, curNumB);
  const { cells, columns, total } = model;
  const speech = `자리별 부분곱 넓이 모델이에요! 직사각형을 자리별로 나누어 부분 넓이들을 더하면 총 넓이는 ${total}${numberJosa(total, '이에요', '예요')}!`;

  const boxesHtml = cells
    .map((cell, i) => renderAreaBox(i, `${cell.width} × ${cell.height}`, cell.area))
    .join('');

  container.innerHTML = `
    <div class="area-model-wrap">
      <div style="text-align:center; max-width:600px;">
        <h3 style="font-family:'Jua'; color:#38bdf8; margin:0 0 6px;">🍫 자리별 부분곱 넓이 모델 (곱셈)</h3>
        <p style="color:var(--text-muted); font-size:0.95rem; margin:0;">
          가로 <strong>${curNumA}</strong>${numberJosa(curNumA, '과', '와')} 세로 <strong>${curNumB}</strong>${numberJosa(curNumB, '을', '를')} 자리별로 나누어 넓이를 구해요!
        </p>
      </div>

      <div class="area-rect-container area-rect-grid" style="grid-template-columns:repeat(${columns}, minmax(0, 1fr));">
        ${boxesHtml}
      </div>

      <div class="area-total">
        전체 넓이(곱) = ${areaSumText(cells.map(cell => cell.area), total, '#10b981')}
      </div>
    </div>
  `;
  studioSpeak(speech);
}

// 테마 초기화
function applyTheme() {
  document.body.className = (currentProfile === 'son') ? 'theme--arcade' : 'theme--slime';
  const tag = document.getElementById('userProfileTag');
  if (tag) {
    tag.textContent = (currentProfile === 'son') ? '🚀 [민수] 5학년 모드' : '🎠 [민서] 1학년 모드';
    tag.style.borderColor = (currentProfile === 'son') ? '#0284c7' : '#ec4899';
    tag.style.color = (currentProfile === 'son') ? '#38bdf8' : '#ec4899';
  }
}

document.addEventListener('DOMContentLoaded', () => {
  applyTheme();
  renderPresetRow(currentOp);
  updateViewTabsUi(currentOp);
  startStudioCalculation(false);
});
